init_scripts:
// Promo-film staging for the CCC static demo. Runs at document start on every page.
// {"ccc-last-seen-version": "5.37", "ccc-whats-new-dismissed-version": "5.37", "ccc-pwa-install-dismissed": "9999999999999", "ccc-telemetry-bar-dismissed": "1", "ccc-tour-done": "1", "ccc-archive-window": "all", "ccc-status-rail-collapsed": "1", "ccc-spawn-cwd": "/home/demo/code/widgets-api", "ccc-separate-tabs": "on", "ccc-sidebar-tab": "queues", "ccc-sidebar-width": "700", "ccc-uxq-selected-scope": "{\"__queue_global__\":\"ALL\"}", "uxq-selected-scope": "{\"__queue_global__\":\"ALL\"}"} is replaced by build-capture.py with the film's localStorage seeds.
(function () {
  window.__CCC_DEMO__ = true;
  window.__CCC_DEMO_FIXTURE_BASE__ = '/api';
  var seeds = {"ccc-last-seen-version": "5.37", "ccc-whats-new-dismissed-version": "5.37", "ccc-pwa-install-dismissed": "9999999999999", "ccc-telemetry-bar-dismissed": "1", "ccc-tour-done": "1", "ccc-archive-window": "all", "ccc-status-rail-collapsed": "1", "ccc-spawn-cwd": "/home/demo/code/widgets-api", "ccc-separate-tabs": "on", "ccc-sidebar-tab": "queues", "ccc-sidebar-width": "700", "ccc-uxq-selected-scope": "{\"__queue_global__\":\"ALL\"}", "uxq-selected-scope": "{\"__queue_global__\":\"ALL\"}"};
  try { Object.keys(seeds).forEach(function (k) { localStorage.setItem(k, seeds[k]); }); } catch (e) {}
  var nativeFetch = window.fetch.bind(window);
  var UUID = /^\/api\/conversations\/([0-9a-f]{8})-[0-9a-f-]{27}$/i;
  document.addEventListener('DOMContentLoaded', function () {
    // Per-session transcripts: /api/conversations/<uuid> -> staged t-<prefix>.json (falls back to the demo mapping).
    var demoFetch = window.fetch;
    window.fetch = function (input, init) {
      try {
        var u = typeof input === 'string' ? input : (input && input.url) || '';
        var m = UUID.exec(u.split('?')[0]);
        if (m && (!init || !init.method || init.method === 'GET')) {
          var staged = '/api/conversations/t-' + m[1].toLowerCase() + '.json';
          return nativeFetch(staged).then(function (r) { return r.ok ? r : demoFetch(input, init); });
        }
      } catch (e) {}
      return demoFetch(input, init);
    };
    var s = document.createElement('style');
    s.textContent = '[data-hf-overlay]{display:none!important}' +
      '#__ccc_demo_ro_banner__,#hiOobePrompt,.hi-oobe,.hi-retention-warning{display:none!important}' +
      'html,body,*{scroll-behavior:auto!important}' +
      '*{caret-color:auto}' +
      // CSS zoom breaks sticky offsets inside the scrolled list; the film never scrolls it.
      '#convList .conv-archived-tools{position:static!important}' +
      // The optimistic "Thinking…" pill after a send never resolves in the static demo.
      '.conv-live-tool-inline.optimistic{display:none!important}' +
      // Search-progress banner under the sidebar search while typing.
      '#convSearchStatus{display:none!important}';
    document.head.appendChild(s);
    document.documentElement.style.zoom = '3';
    // The demo repo list renders one unlabeled folder chip; drop it.
    var scrub = function () {
      document.querySelectorAll('.spawn-cwd-chip').forEach(function (b) {
        if (b.textContent.trim() === '[object Object]') b.remove();
      });
    };
    new MutationObserver(scrub).observe(document.body, { childList: true, subtree: true });
    scrub();
  });
})();
// Static demo: mutating calls are no-ops, so mirror the real enqueue by prepending the new ticket
// to the next /api/queue/list read (same shape as the fixture rows).
var added = null;
(function () {
  var oj = Response.prototype.json;
  Response.prototype.json = function () {
    var url = this.url || '';
    return oj.call(this).then(function (d) {
      if (added && /\/api\/queue\/list/.test(url) && d && Array.isArray(d.items) && d.items.indexOf(added) < 0) {
        d.items = [added].concat(d.items); d.count = d.items.length;
      }
      return d;
    });
  };
})();
document.addEventListener('DOMContentLoaded', function () {
  var f = window.fetch;
  window.fetch = function (input, init) {
    var u = typeof input === 'string' ? input : (input && input.url) || '';
    if (/\/api\/ux-fixes\/enqueue/.test(u) && init && init.body) {
      try {
        var b = JSON.parse(init.body);
        added = { ref: (b.project || 'BUGS') + '-113', number: 113, project: b.project || 'BUGS', status: 'open',
          note: b.note, text: b.note, type: 'feature', priority: 'p0', source: 'ccc',
          created_at: '2026-10-09T08:00:00Z', updated_at: '2026-10-09T08:00:00Z', claimable: true, watchtower_runnable: true };
      } catch (e) {}
    }
    return f(input, init);
  };
});
// Software-rendered 4K cannot afford the modal's backdrop blur (video froze in 8 s bursts); keep the dim, drop the blur.
document.addEventListener('DOMContentLoaded', function () {
  var s = document.createElement('style');
  s.textContent = '*{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}';
  document.head.appendChild(s);
});
